CREATE OR REPLACE FUNCTION private.bank_document_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_account public.business_bank_accounts%rowtype;v_selected uuid;v_transfer boolean;v_capture boolean;v_series uuid;
begin
 if tg_op='UPDATE' and new.owner_id is distinct from old.owner_id then raise exception 'La empresa del documento no se puede modificar.'; end if;
 if tg_op='UPDATE' and old.bank_snapshot_source is not null then
  if new.bank_account_id is distinct from old.bank_account_id or new.bank_account_snapshot is distinct from old.bank_account_snapshot
   or new.bank_snapshot_source is distinct from old.bank_snapshot_source or new.bank_snapshot_at is distinct from old.bank_snapshot_at then raise exception 'La cuenta bancaria guardada en el documento no se puede modificar.'; end if;
  return new;
 end if;
 if new.bank_account_snapshot is not null or new.bank_snapshot_source is not null or new.bank_snapshot_at is not null then raise exception 'La cuenta bancaria del documento la guarda el servidor.'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner_id::text||':business-bank-accounts',0));
 v_selected:=new.bank_account_id;
 if v_selected is not null and not exists(select 1 from public.business_bank_accounts where owner_id=new.owner_id and id=v_selected and archived_at is null and validation_status='valid') then raise exception 'La cuenta bancaria seleccionada no está disponible.'; end if;
 if tg_table_name='sales_invoices' then v_capture:=new.status<>'draft';v_series:=new.series_id;else v_capture:=true;end if;
 if not v_capture then return new; end if;
 if v_selected is null and v_series is not null then
  select a.id into v_selected from public.sales_invoice_series s join public.business_bank_accounts a on a.owner_id=s.owner_id and a.id=s.default_bank_account_id
   where s.id=v_series and s.owner_id=new.owner_id and a.archived_at is null and a.validation_status='valid';
 end if;
 if v_selected is null then select id into v_selected from public.business_bank_accounts where owner_id=new.owner_id and is_default and archived_at is null and validation_status='valid';end if;
 -- Existing documents stored display labels. New documents carry stable method IDs.
 v_transfer:=new.payment_method_id='bank_transfer' or (new.payment_method_id is null and lower(btrim(coalesce(new.payment_method,''))) in ('transferencia bancaria','transferencia','bank transfer'));
 if v_selected is null and coalesce(v_transfer,false) then raise exception 'Falta una cuenta bancaria en Configuración → General';end if;
 if v_selected is not null then
  select * into v_account from public.business_bank_accounts where owner_id=new.owner_id and id=v_selected and archived_at is null and validation_status='valid';
  new.bank_account_id:=v_account.id;
  new.bank_account_snapshot:=jsonb_build_object('version',1,'accountId',v_account.id,'alias',v_account.alias,'iban',v_account.iban,'bic',v_account.bic,'holder',v_account.holder);
 end if;
 new.bank_snapshot_source:=case when tg_table_name='sales_receipts' then 'receipt_created' else 'issued' end;
 new.bank_snapshot_at:=transaction_timestamp();return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_sales_invoice_line_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_invoice_id uuid;
  v_status text;
begin
  v_invoice_id := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;
  select status into v_status from public.sales_invoices where id = v_invoice_id;

  -- During ON DELETE CASCADE the parent draft may already be invisible to this lookup.
  -- Deleting an issued invoice is still blocked by private.guard_sales_invoice_immutable()
  -- on public.sales_invoices before the cascade can run.
  if tg_op = 'DELETE' and v_status is null then
    return old;
  end if;

  if v_status is distinct from 'draft' then
    raise exception 'Las líneas de una factura emitida no se pueden modificar.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_sales_receipt_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_total numeric;
  v_paid numeric;
begin
  select total_amount into v_total from public.sales_receipts where id=new.receipt_id;
  if v_total is null then raise exception 'Recibo no encontrado.'; end if;

  select coalesce(sum(amount),0) into v_paid
  from public.sales_receipt_payments
  where receipt_id=new.receipt_id
    and (tg_op='INSERT' or id<>new.id);

  if v_paid+new.amount > v_total+0.005 then
    raise exception 'El cobro no puede superar el importe pendiente del recibo.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.mfa_impl_687058(p_source_id uuid, p_destination_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := private.app_workspace_owner_id();
  v_source public.clients%rowtype;
  v_destination public.clients%rowtype;
  v_actor uuid := auth.uid();
  v_actor_email text;
  v_invoice_count integer := 0;
  v_alias_count integer := 0;
begin
  if not coalesce(private.app_is_admin(),false) then
    raise exception 'Solo un administrador puede fusionar clientes.';
  end if;
  if p_source_id is null or p_destination_id is null or p_source_id=p_destination_id then
    raise exception 'El cliente origen y destino deben ser distintos.';
  end if;

  select * into v_source
  from public.clients
  where id=p_source_id and owner_id=v_owner
  for update;
  if not found then raise exception 'Cliente origen no encontrado en este workspace.'; end if;

  select * into v_destination
  from public.clients
  where id=p_destination_id and owner_id=v_owner
  for update;
  if not found then raise exception 'Cliente destino no encontrado en este workspace.'; end if;

  if nullif(regexp_replace(upper(coalesce(v_source.tax_id,'')),'[^A-Z0-9]','','g'),'') is not null
     and nullif(regexp_replace(upper(coalesce(v_destination.tax_id,'')),'[^A-Z0-9]','','g'),'') is not null
     and regexp_replace(upper(v_source.tax_id),'[^A-Z0-9]','','g')
       <> regexp_replace(upper(v_destination.tax_id),'[^A-Z0-9]','','g') then
    raise exception 'Los clientes tienen identificaciones fiscales diferentes. Revisa la fusión manualmente.';
  end if;

  select count(*) into v_invoice_count from public.sales_invoices where owner_id=v_owner and client_id=p_source_id;
  select count(*) into v_alias_count from public.entity_alias_rules where owner_id=v_owner and entity_type='client' and target_entity_id=p_source_id;

  update public.clients
  set
    tax_id=coalesce(nullif(trim(v_destination.tax_id),''),v_source.tax_id),
    email=coalesce(nullif(trim(v_destination.email),''),v_source.email),
    phone=coalesce(nullif(trim(v_destination.phone),''),v_source.phone),
    address_line1=coalesce(nullif(trim(v_destination.address_line1),''),v_source.address_line1),
    address_line2=coalesce(nullif(trim(v_destination.address_line2),''),v_source.address_line2),
    postal_code=coalesce(nullif(trim(v_destination.postal_code),''),v_source.postal_code),
    city=coalesce(nullif(trim(v_destination.city),''),v_source.city),
    province=coalesce(nullif(trim(v_destination.province),''),v_source.province),
    notes=case
      when nullif(trim(coalesce(v_destination.notes,'')),'') is null then v_source.notes
      when nullif(trim(coalesce(v_source.notes,'')),'') is null then v_destination.notes
      when position(v_source.notes in v_destination.notes)>0 then v_destination.notes
      else v_destination.notes || E'\n' || v_source.notes
    end
  where id=p_destination_id and owner_id=v_owner;

  update public.sales_invoices
  set client_id=p_destination_id
  where owner_id=v_owner and client_id=p_source_id;

  update public.entity_alias_rules
  set target_entity_id=p_destination_id
  where owner_id=v_owner and entity_type='client' and target_entity_id=p_source_id;

  delete from public.clients where id=p_source_id and owner_id=v_owner;

  select email into v_actor_email from public.app_users where user_id=v_actor limit 1;
  insert into public.audit_logs(
    workspace_owner_id,actor_user_id,actor_email,module,action,
    entity_type,entity_id,entity_label,summary,details
  ) values (
    v_owner,v_actor,v_actor_email,'settings','merge','clients',
    p_destination_id::text,v_destination.name,
    'Fusionó cliente '||v_source.name||' en '||v_destination.name,
    jsonb_build_object(
      'source_id',p_source_id,'destination_id',p_destination_id,
      'source_name',v_source.name,'destination_name',v_destination.name,
      'affected',jsonb_build_object('sales_invoices',v_invoice_count,'aliases',v_alias_count)
    )
  );

  return jsonb_build_object(
    'ok',true,'sourceId',p_source_id,'destinationId',p_destination_id,
    'affected',jsonb_build_object('salesInvoices',v_invoice_count,'aliases',v_alias_count)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.recalculate_sales_receipt_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_receipt_id uuid;
begin
  v_receipt_id:=case when tg_op='DELETE' then old.receipt_id else new.receipt_id end;
  update public.sales_receipts
  set total_amount=coalesce((select round(sum(line_total),2) from public.sales_receipt_lines where receipt_id=v_receipt_id),0)
  where id=v_receipt_id;
  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION private.sales_invoice_line_calculate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_gross numeric;
  v_net numeric;
  v_type text;
  v_document_kind text;
  v_fiscal_treatment text;
  v_shopify_tax_included boolean := false;
begin
  select invoice_type,document_kind,fiscal_treatment
    into v_type,v_document_kind,v_fiscal_treatment
  from public.sales_invoices where id=new.invoice_id;

  if v_type is null then raise exception 'Documento de venta no encontrado.'; end if;
  if v_type='standard' and new.unit_price < 0 then
    raise exception 'Un documento de venta ordinario no puede tener precios negativos.';
  end if;
  if v_document_kind='receipt'
     and v_fiscal_treatment in ('exempt','non_taxable','out_of_scope')
     and coalesce(new.tax_rate,0)<>0
  then
    raise exception 'Los recibos exentos o no sujetos deben tener IVA 0 %%.';
  end if;

  v_gross := new.quantity * new.unit_price;
  v_net := v_gross * (1 - new.discount_percent / 100);
  new.line_net := round(v_net,2);
  -- Shopify tax-inclusive prices calculate VAT before rounding the net base.
  -- Scope by source row AND owner; manual invoices, Amazon and receipts retain their rules.
  v_shopify_tax_included := private.sales_shopify_tax_included(new.invoice_id);
  new.tax_amount := round((case when v_shopify_tax_included then v_net else new.line_net end) * new.tax_rate / 100,2);
  new.line_total := new.line_net + new.tax_amount;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_sales_payment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_invoice_id uuid;
  v_owner uuid;
  v_paid numeric;
  v_total numeric;
  v_status text;
  v_allow_partial boolean;
  v_auto_paid boolean;
begin
  v_invoice_id := case when tg_op='DELETE' then old.invoice_id else new.invoice_id end;

  select owner_id,total_amount,status
    into v_owner,v_total,v_status
  from public.sales_invoices
  where id=v_invoice_id;

  if v_status='draft' then
    raise exception 'No se pueden registrar cobros sobre una factura en borrador.';
  end if;

  select coalesce(sum(amount),0)
    into v_paid
  from public.sales_payments
  where invoice_id=v_invoice_id;

  v_allow_partial := private.sales_setting_boolean(v_owner,'allowPartialPayments',true);
  v_auto_paid := private.sales_setting_boolean(v_owner,'autoMarkPaid',true);

  if not v_allow_partial
     and v_paid > 0.005
     and v_total > 0
     and v_paid < v_total - 0.005
  then
    raise exception 'Los cobros parciales están desactivados para este espacio de trabajo.';
  end if;

  update public.sales_invoices
  set status=case
      when v_paid>=v_total-0.005 and v_total>0 and v_auto_paid then 'paid'
      when v_paid>0.005 then 'partially_paid'
      when v_status in ('paid','partially_paid') then 'issued'
      else v_status
    end,
    paid_at=case
      when v_paid>=v_total-0.005 and v_total>0 and v_auto_paid then coalesce(paid_at,now())
      else null
    end
  where id=v_invoice_id;

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_sales_invoice(p_invoice_id uuid)
 RETURNS sales_invoices
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_invoice public.sales_invoices%rowtype;
  v_series public.sales_invoice_series%rowtype;
  v_number integer;
begin
  select * into v_invoice from public.sales_invoices where id=p_invoice_id for update;
  if v_invoice.id is null then raise exception 'Factura no encontrada.'; end if;
  if v_invoice.status <> 'issued' then raise exception 'Solo se puede reabrir una factura que esté únicamente emitida.'; end if;
  if v_invoice.sent_at is not null or v_invoice.paid_at is not null or exists(select 1 from public.sales_payments p where p.invoice_id=v_invoice.id) then
    raise exception 'La factura ya se ha enviado o tiene cobros y no se puede reabrir.';
  end if;

  select * into v_series from public.sales_invoice_series where id=v_invoice.series_id for update;
  if v_series.id is null then raise exception 'Serie no encontrada.'; end if;
  if v_invoice.invoice_number is null or left(v_invoice.invoice_number, char_length(v_series.prefix)) <> v_series.prefix then
    raise exception 'No se pudo recuperar el número de factura.';
  end if;

  v_number := substring(v_invoice.invoice_number from char_length(v_series.prefix)+1)::integer;
  insert into public.sales_invoice_released_numbers(owner_id,series_id,number)
  values(v_invoice.owner_id,v_invoice.series_id,v_number)
  on conflict do nothing;

  update public.sales_invoices
  set status='draft', invoice_number=null, reserved_number=v_number, issued_at=null,
      client_name=null, client_tax_id=null, client_email=null, client_address=null,
      issuer_name=null, issuer_tax_id=null, issuer_email=null, issuer_address=null
  where id=v_invoice.id
  returning * into v_invoice;

  return v_invoice;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_shopify_order_invoice(p_order_id uuid, p_client jsonb, p_series_id uuid, p_issue_date date, p_lines jsonb, p_issue boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=private.app_workspace_owner_id();
  v_order public.fulfillment_orders%rowtype;
  v_invoice public.sales_invoices%rowtype;
  v_key text; v_client_id uuid; v_line jsonb; v_position integer:=0;
begin
  if auth.uid() is null or not private.app_has_permission('sales') or not private.app_has_permission('orders') then raise exception 'Sin permiso para facturar pedidos.'; end if;
  select * into v_order from public.fulfillment_orders where id=p_order_id and owner_id=v_owner;
  if v_order.id is null or v_order.source_channel<>'shopify' or v_order.source_integration_account_id is null or v_order.order_id is null then raise exception 'Pedido directo de Shopify no encontrado.'; end if;
  v_key:='shopify:'||v_order.source_integration_account_id::text||':'||v_order.order_id;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||v_key,0));
  select * into v_invoice from public.sales_invoices where owner_id=v_owner and source_order_key=v_key for update;
  if v_invoice.id is not null and v_invoice.status<>'draft' then return v_invoice.id; end if;
  if coalesce(v_order.raw_payload->>'cancelledAt','')<>'' or coalesce(v_order.raw_payload->>'displayFinancialStatus','') ~ 'REFUNDED|VOIDED' then raise exception 'Revisa cancelaciones o reembolsos antes de facturar.'; end if;
  if jsonb_typeof(v_order.raw_payload->'taxesIncluded') is distinct from 'boolean' then raise exception 'Actualizar pedidos: faltan datos fiscales de Shopify.'; end if;
  if coalesce((v_order.raw_payload#>>'{lineItems,pageInfo,hasNextPage}')::boolean,false) or coalesce((v_order.raw_payload#>>'{shippingLines,pageInfo,hasNextPage}')::boolean,false) then raise exception 'El desglose de líneas de Shopify está incompleto.'; end if;
  if coalesce(trim(p_client->>'name'),'')='' or coalesce(trim(p_client->>'addressLine1'),'')='' or coalesce(trim(p_client->>'postalCode'),'')='' or coalesce(trim(p_client->>'city'),'')='' or coalesce(p_client->>'countryCode','') !~ '^[A-Z]{2}$' then raise exception 'Completa los datos de facturación del cliente.'; end if;
  if nullif(p_client->>'taxRegistrationId','') is not null and not exists(select 1 from public.business_tax_registrations where id=(p_client->>'taxRegistrationId')::uuid and owner_id=v_owner and active) then raise exception 'Registro IVA no disponible.'; end if;
  if p_issue_date is null or not exists(select 1 from public.sales_invoice_series where id=p_series_id and owner_id=v_owner and active and kind='standard' and year=extract(year from p_issue_date)::int) then raise exception 'La serie no corresponde a la fecha de la factura.'; end if;
  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines)=0 then raise exception 'La factura no tiene líneas.'; end if;
  select id into v_client_id from public.clients where owner_id=v_owner and active
    and name=trim(p_client->>'name') and coalesce(tax_id,'')=coalesce(trim(p_client->>'taxId'),'')
    and coalesce(email,'')=coalesce(trim(p_client->>'email'),'')
    and coalesce(address_line1,'')=coalesce(p_client->>'addressLine1','')
    and coalesce(address_line2,'')=coalesce(p_client->>'addressLine2','')
    and coalesce(postal_code,'')=coalesce(p_client->>'postalCode','')
    and coalesce(city,'')=coalesce(p_client->>'city','')
    and coalesce(province,'')=coalesce(p_client->>'province','')
    and country_code=p_client->>'countryCode' limit 1;
  if v_client_id is null then
    insert into public.clients(owner_id,name,tax_id,email,phone,address_line1,address_line2,postal_code,city,province,country_code,notes)
    values(v_owner,trim(p_client->>'name'),nullif(trim(p_client->>'taxId'),''),nullif(trim(p_client->>'email'),''),nullif(p_client->>'phone',''),p_client->>'addressLine1',p_client->>'addressLine2',p_client->>'postalCode',p_client->>'city',p_client->>'province',p_client->>'countryCode','Cliente del pedido '||v_order.order_number) returning id into v_client_id;
  end if;
  if v_invoice.id is null then
    insert into public.sales_invoices(owner_id,client_id,series_id,issue_date,operation_date,currency,notes,tax_registration_id,source_order_key,source_fulfillment_order_id)
    values(v_owner,v_client_id,p_series_id,p_issue_date,v_order.order_created_at::date,coalesce(v_order.currency,'EUR'),'Pedido Shopify '||coalesce(v_order.order_number,v_order.order_id),nullif(p_client->>'taxRegistrationId','')::uuid,v_key,p_order_id) returning * into v_invoice;
  else
    update public.sales_invoices set tax_registration_id=nullif(p_client->>'taxRegistrationId','')::uuid,client_id=v_client_id,series_id=p_series_id,issue_date=p_issue_date where id=v_invoice.id;
    delete from public.sales_invoice_lines where invoice_id=v_invoice.id;
  end if;
  for v_line in select value from jsonb_array_elements(p_lines) loop
    v_position:=v_position+1;
    insert into public.sales_invoice_lines(owner_id,invoice_id,position,description,quantity,unit,unit_price,discount_percent,tax_rate)
    values(v_owner,v_invoice.id,v_position,v_line->>'description',(v_line->>'quantity')::numeric,coalesce(v_line->>'unit','ud'),(v_line->>'unitPrice')::numeric,coalesce((v_line->>'discountPercent')::numeric,0),(v_line->>'taxRate')::numeric);
  end loop;
  select * into v_invoice from public.sales_invoices where id=v_invoice.id;
  if v_order.total_amount is null or v_invoice.total_amount<>round(v_order.total_amount,2) then raise exception 'El total de la factura no cuadra con Shopify.'; end if;
  update public.sales_invoices set bank_account_id=case when p_client ? 'bankAccountId' then nullif(p_client->>'bankAccountId','')::uuid else bank_account_id end,payment_method_id=nullif(p_client->>'paymentMethodId',''),payment_method=nullif(p_client->>'paymentMethod','') where id=v_invoice.id and status='draft';
  if p_issue then perform public.issue_sales_invoice(v_invoice.id); end if;
  return v_invoice.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_sales_invoice_number(p_invoice_id uuid, p_invoice_number text)
 RETURNS sales_invoices
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_invoice public.sales_invoices%rowtype;
  v_series public.sales_invoice_series%rowtype;
  v_new text:=trim(coalesce(p_invoice_number,''));
  v_old text;
  v_suffix text;
  v_old_suffix text;
  v_value integer;
  v_old_value integer;
begin
  if auth.uid() is null then raise exception 'Sesión no válida.'; end if;
  select * into v_invoice from public.sales_invoices where id=p_invoice_id for update;
  if v_invoice.id is null then raise exception 'Factura no encontrada.'; end if;
  if v_invoice.owner_id <> private.app_workspace_owner_id() or not private.app_has_permission('sales') then raise exception 'Sin permiso para modificar la factura.'; end if;
  if v_new='' then raise exception 'Indica un número de factura.'; end if;
  select * into v_series from public.sales_invoice_series where id=v_invoice.series_id for update;
  if v_series.id is null then raise exception 'Serie no encontrada.'; end if;
  if left(v_new,length(v_series.prefix))<>v_series.prefix then raise exception 'El número debe comenzar por el prefijo de la serie: %',v_series.prefix; end if;
  v_suffix:=substring(v_new from length(v_series.prefix)+1);
  if v_suffix !~ '^[0-9]+$' then raise exception 'El número debe terminar en una parte numérica.'; end if;
  v_value:=v_suffix::integer;
  if v_value<1 then raise exception 'El número debe ser mayor que cero.'; end if;
  if exists(select 1 from public.sales_invoices where owner_id=v_invoice.owner_id and invoice_number=v_new and id<>v_invoice.id) then raise exception 'Ya existe una factura con el número %.',v_new; end if;
  v_old:=v_invoice.invoice_number;
  if v_old is not distinct from v_new then return v_invoice; end if;
  update public.sales_invoices set invoice_number=v_new,updated_at=now() where id=v_invoice.id returning * into v_invoice;
  delete from public.sales_invoice_released_numbers where owner_id=v_invoice.owner_id and series_id=v_series.id and number=v_value;
  if v_value>=v_series.next_number then update public.sales_invoice_series set next_number=v_value+1,updated_at=now() where id=v_series.id; end if;
  if v_old is not null and left(v_old,length(v_series.prefix))=v_series.prefix then
    v_old_suffix:=substring(v_old from length(v_series.prefix)+1);
    if v_old_suffix ~ '^[0-9]+$' then
      v_old_value:=v_old_suffix::integer;
      if not exists(select 1 from public.sales_invoices where owner_id=v_invoice.owner_id and invoice_number=v_old) then
        insert into public.sales_invoice_released_numbers(owner_id,series_id,number) values(v_invoice.owner_id,v_series.id,v_old_value) on conflict do nothing;
      end if;
    end if;
  end if;
  return v_invoice;
end;
$function$
